def rrf(lists, k=60):
    s = {}
    for lst in lists:
        for r, d in enumerate(lst, 1):
            s[d] = s.get(d, 0) + 1 / (k + r)
    return sorted(s, key=s.get, reverse=True)

lexical  = ["떡볶이집A", "분식B", "떡볶이밀키트"]   # 글자가 맞는 것
semantic = ["분식B", "로제떡볶이C", "떡볶이집A"]    # 뜻이 가까운 것
print(rrf([lexical, semantic]))
# ['분식B', '떡볶이집A', '로제떡볶이C', '떡볶이밀키트']
